def main():
    import sys
    input = sys.stdin.read
    data = input().split('\n')

    events = []
    for i in range(1, len(data)):
        event_type, *event_data = data[i].split()
        if event_type == 'P':
            events.append((int(event_data[0]), None))
        else:
            events.append((None, int(event_data[0])))

    events.sort(key=lambda x: x[0] if x[0] is not None else float('inf'))

    current_seats = 0
    can_take_bus = True

    for event in events:
        if event[0] is not None:
            current_seats += event[0]
            if current_seats >= event[1]:
                current_seats -= event[1]
                can_take_bus = True
            else:
                can_take_bus = False
                break
        else:
            if not can_take_bus:
                print("NO")
                return
            print("YES")

if __name__ == "__main__":
    main()

def min_seconds_to_display(s, t):
    if s == t:
        return len(s)

    n = len(s)
    m = len(t)

    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1

    return dp[n][m]

